// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 guess) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        uint256 targetBlock;
        vm.deal(actor, 1 ether);
        vm.startPrank(actor);
        c.lockInGuess{value: 1 ether}(guess);
        // settle() requires block.number > guesses[actor].block; roll forward to exactly the target block
        // guessed.block == block.number+1 at lock time
        targetBlock = block.number; // current block is now the pre-roll one; compute target
        vm.roll(block.number + 1); // block.number + 1 == the stored target block
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        vm.stopPrank();

        // Universal rule: at block.number == target block, settle() MUST revert.
        assertTrue(!ok, "settle must not be settleable in the block it targets");
    }
}
